{
  "name": "loss_diff_squared_advantage",
  "intuition": "Use a regression paradigm on advantage differences, penalizing squared error between predicted preference margin (log_prob difference) and advantage signal, encouraging calibrated margin predictions.",
  "pseudocode": "predicted_margin = lpw - lpl\nerror = predicted_margin - advantage_gap\nloss = mean(weight * error^2)",
  "hyperparams": {
    "paradigm_family": "pairwise_regression",
    "signal_family": "advantage_gap",
    "link_family": "identity",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["sub", "mul", "mean", "add", "pow"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_gap = batch['advantage_gap']\n    pred_margin = ops.sub(lpw, lpl)\n    error = ops.sub(pred_margin, adv_gap)\n    squared_error = ops.mul(error, error)\n    if weight is not None:\n        weighted_error = ops.mul(squared_error, weight)\n    else:\n        weighted_error = squared_error\n    return ops.mean(weighted_error)"
}

{
  "name": "pairwise_pref_cost_gap",
  "intuition": "This loss compares pairs of samples emphasizing the cost gap between them, promoting preferences that favor lower cost pairs. By weighting pairs according to their cost_gap, it encourages the model to prefer outcomes with smaller costs, aligning with lower-is-better objectives in RL4CO.",
  "pseudocode": "loss = mean( logsigmoid( (log_prob_w - log_prob_l) * weight * scale ) ) where scale = ops.reciprocal(ops.abs(cost_gap) + epsilon)",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "costs",
    "link_family": "pairwise",
    "agg_family": "mean",
    "constraint_family": "preference"
  },
  "operators_used": ["logsigmoid", "abs", "mul", "add", "reciprocal", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\\n    epsilon = 1e-8\\n    log_prob_w = batch['log_prob_w']\\n    log_prob_l = batch['log_prob_l']\\n    weight = batch['weight']\\n    cost_gap = batch['cost_gap']\\n\\n    scale = ops.reciprocal(ops.abs(cost_gap) + epsilon)\\n    diff = log_prob_w - log_prob_l\\n    scaled_diff = diff * weight * scale\\n\\n    loss = ops.mean(ops.logsigmoid(scaled_diff))\\n    return loss"
}

{
  "name": "loss_advantage_tanh_rank_000",
  "intuition": "A pairwise loss using a rank-based gap of advantages passed through a tanh nonlinearity to smooth and bound the signal, shifting paradigm from margin-based to rank-based aggregation, with advantage signals enhancing gradient guidance.",
  "pseudocode": "adv_gap = advantage_w - advantage_l\nranked_gap = rank_gap(adv_gap)\nsmooth_gap = tanh(ranked_gap * scale)\nloss = relu(-smooth_gap) * weight\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_rank_based",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_zero_clip"
  },
  "operators_used": ["rank_gap", "tanh", "relu", "mean", "sub", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    adv_gap = ops.sub(adv_w, adv_l)\n    ranked_gap = ops.rank_gap(adv_gap)\n    smooth_gap = ops.tanh(ops.mul(ranked_gap, scale))\n    loss = ops.relu(ops.neg(smooth_gap))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
}

{
  "name": "loss_logsigmoid_000_cost",
  "intuition": "This loss stabilizes the pairwise logsigmoid by clamping its input between -20 and 20 to prevent numerical overflow or underflow, and incorporates a scaled difference between winning and losing log probabilities modulated by alpha and scale hyperparameters. The subtraction of 0.1 * cost gap helps incorporate cost-based preference signal. Clamping ensures numerical stability while preserving meaningful gradients, enabling effective discrimination between pairs.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_a",
      "cost_b"
    ]
  }
}

