{
  "name": "loss_rank_gap_tanh_advantage",
  "intuition": "Shift from margin-based pairwise losses to a rank-based loss using a bounded non-linear transformation (tanh) on advantage signals to stabilize training and better capture preference strength.",
  "pseudocode": "rank_gap = rank_gap(advantage_w - advantage_l)\nscaled_gap = tanh(beta * rank_gap)\nloss = mean(weight * (1 - scaled_gap))",
  "hyperparams": {
    "paradigm_family": "pairwise_rank_based",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["rank_gap", "tanh", "mean", "sub", "mul", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 1.0)))\n    gap = adv_w - adv_l\n    rank_g = ops.rank_gap(gap)\n    scaled_gap = ops.tanh(beta * rank_g)\n    loss = weight * (1 - scaled_gap)\n    return loss.mean()"
}

{
  "name": "pairwise_cost_gap_obj_loss",
  "intuition": "This loss encourages ordering of pairs based on the cost gap signal, which measures the difference in actual costs between chosen and alternative options, promoting preference for lower-cost choices. Incorporating the log probabilities ensures it is a likelihood-based comparison, suitable for RL settings where relative rankings are crucial.",
  "pseudocode": "loss = mean_over_pairs( max(0, (log_prob_l - log_prob_w) * cost_gap) )",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "cost",
    "link_family": "difference",
    "agg_family": "mean",
    "constraint_family": "none",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "sub", "mul", "max", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap = batch.get('cost_gap', ops.zeros_like(log_prob_w))\n    # Compute pairwise difference weighted by cost gap\n    diff = ops.sub(log_prob_l, log_prob_w)\n    weighted_diff = ops.mul(diff, cost_gap)\n    # Apply hinge: only penalize if weighted diff > 0 (i.e., incorrect ordering)\n    hinge_loss = ops.relu(weighted_diff)\n    # Average over pairs to get scalar loss\n    loss = ops.mean(hinge_loss)\n    return loss"
}

{
  "name": "pairwise_pref_loss",
  "intuition": "Uses a pairwise comparison of log probabilities weighted by costs or advantages to encourage preferred sequences. By combining the difference in log probabilities (indicating preference strength) with a cost or advantage signal, it promotes selecting higher-quality outputs. The signal ensures the loss aligns with the objective, especially in lower-is-better scenarios, making it suitable for preference-based training in RL4CO.",
  "pseudocode": "loss = mean(negative(logsigmoid((log_prob_w - log_prob_l) * weight)) * (cost_signal))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost_advantage",
    "link_family": "sigmoid",
    "agg_family": "pairwise",
    "constraint_family": "pairwise"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch.get('cost_gap', None)\n    # Use cost_gap if available; fallback to zeros\n    cost_signal = cost_gap if cost_gap is not None else 0.0\n    diff = log_prob_w - log_prob_l\n    weighted_diff = diff * weight\n    loss = -ops.logsigmoid(weighted_diff)\n    return ops.mean(loss * ops.stop_gradient(ops.tanh(cost_signal)))"
}

