{
  "name": "loss_diff_exp_advantage_repaired",
  "intuition": "Parabolic penalization of advantage difference with exponential sensitivity ensuring autograd-safe ops and proper grad flow",
  "pseudocode": "gap_adv = advantage_w - advantage_l\nscaled_gap = alpha * gap_adv\nloss = weight * (exp(scaled_gap) - 1)^2\nloss = mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_regression",
    "signal_family": "advantage_gap",
    "link_family": "exponential",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["exp", "sub", "mul", "mean", "add", "ones_like"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    gap_adv = ops.sub(adv_w, adv_l)\n    scaled_gap = ops.mul(alpha, gap_adv)\n    exp_term = ops.exp(scaled_gap)\n    ones = ops.ones_like(exp_term)\n    diff = ops.sub(exp_term, ones)\n    loss = ops.mul(diff, diff)\n    loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
}

{
  "name": "pairwise_cost_gap_logs",
  "intuition": "This loss penalizes pairs with large cost differences (cost_b - cost_a) while encouraging higher log probabilities for preferred options. Using a sigmoid-based link function on the difference in log probs and cost gap creates a smooth, differentiable surface that emphasizes preference consistency, aiding stable RL training in combinatorial optimization scenarios.",
  "pseudocode": "loss = sum(-logsigmoid(alpha * (log_prob_w - log_prob_l) - beta * (cost_b - cost_a)))",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "optional adjustment parameters"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    alpha = float(extra.get('alpha', 1.0))\n    beta = float(extra.get('beta', 1.0))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    diff_probs = lpw - lpl\n    gap = cost_b - cost_a\n    x = alpha * diff_probs - beta * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x) * weight\n    return ops.mean(loss)"
}

{
  "name": "pairwise_cost_gap_logsigmoid_sum_loss",
  "intuition": "This loss encourages the model to assign higher probabilities to preferred options by penalizing cases where the log probability of a worse option exceeds that of a better one, scaled appropriately. Using cost_gap as a signal emphasizes the importance of relative cost differences, and the sum aggregation ensures the total loss accounts for all pairwise comparisons efficiently. Clamping stabilizes training, while the logsigmoid enforces a margin-based contrastive preference alignment.",
  "pseudocode": "loss = sum(-logsigmoid(clamp(alpha * scale * (log_prob_w - log_prob_l) - margin, min_value, max_value)) * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "sum",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "optional parameters for scaling and margin"
  },
  "operators_used": ["logsigmoid", "clamp", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    margin = float(extra.get('hyperparams', {}).get('margin', 0.0))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = cost_b - cost_a\n    x = alpha * scale * (lpw - lpl) - margin\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x) * weight\n    return ops.sum(loss)"
}

{
