  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    advantage_gap = batch['advantage_gap']\n    delta_rank = batch['delta_rank']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 0.1)))\n    gamma = float(extra.get('gamma', extra.get('hyperparams', {}).get('gamma', 0.5)))\n    rank_weight = ops.clamp(ops.add(1.0, ops.mul(gamma, delta_rank)), 0.1, 10.0)\n    margin = ops.sub(lpw, lpl)\n    dist_margin = ops.sub(ops.mul(alpha, margin), ops.mul(beta, advantage_gap))\n    x_tanh = ops.tanh(dist_margin)\n    loss_per_pair = ops.neg(ops.logsigmoid(x_tanh))\n    loss_weighted = ops.mul(ops.mul(loss_per_pair, weight), ops.pow(rank_weight, 2.0))\n    norm = ops.sum(ops.mul(weight, ops.pow(rank_weight, 2.0))) + eps\n    return ops.div(ops.sum(loss_weighted), norm)"
