{
  "name": "pairwise_margin_smooth_tanh",
  "intuition": "This loss employs a smooth tanh transformation on the margin (log_prob_w - log_prob_l) to avoid hard clipping and promote stable gradient flow. By integrating advantage_gap into the margin through the tanh, the loss emphasizes pairs with significant advantage differences, thus sharpening the ranking signal while preventing gradient saturation. The pairwise nature ensures direct comparison between candidate pairs, making it suitable for RL4CO preferences.",
  "pseudocode": "margin = log_prob_w - log_prob_l\nsmoothed_margin = tanh(alpha * margin - beta * advantage_gap)\nloss_per_pair = -logsigmoid(smoothed_margin)\nweighted_loss = loss_per_pair * weight\nloss = sum(weighted_loss) / (sum(weight) + epsilon)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_gap",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "smooth_transform",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "tanh", "clamp", "mul", "sum", "add", "div", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    advantage_gap = batch['advantage_gap']\n\n    alpha = float(extra.get('alpha', 1.0))\n    beta = float(extra.get('beta', 0.1))\n\n    margin = ops.sub(lpw, lpl)\n    smoothed_margin = ops.tanh(ops.sub(ops.mul(alpha, margin), ops.mul(beta, advantage_gap)))\n    loss_per_pair = ops.neg(ops.logsigmoid(smoothed_margin))\n    weighted_loss = ops.mul(loss_per_pair, weight)\n    loss = ops.div(ops.sum(weighted_loss), ops.sum(weight) + eps)\n    return loss"
}

{
  "name": "relu_neg_logprob_cost_a_weighted",
  "intuition": "Penalize pairs where the loser has higher log probability than winner, weighted by how much better the winner's cost_a is, encouraging correct ordering.",
  "pseudocode": "cost_diff = batch['cost_a']\nlog_prob_diff = batch['log_prob_w'] - batch['log_prob_l']\nloss_per_pair = batch['weight'] * relu(-log_prob_diff) * relu(cost_diff)\nreturn loss_per_pair.mean()",
  "hyperparams": {
    "paradigm_family": "pairwise_preference",
    "signal_family": "cost",
    "link_family": "relu",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["relu", "sub", "neg", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    cost_diff = batch['cost_a']\n    log_prob_diff = batch['log_prob_w'] - batch['log_prob_l']\n    relu_neg_log_prob_diff = ops.relu(-log_prob_diff)\n    relu_cost_diff = ops.relu(cost_diff)\n    loss_per_pair = batch['weight'] * relu_neg_log_prob_diff * relu_cost_diff\n    return loss_per_pair.mean()\n"
}

{
  "name": "unnamed_free_loss",
  "intuition": "Fixed joint preference violation by enforcing a positive margin directly on the difference between winning and losing log probabilities, ensuring that the model properly prioritizes higher log_prob_w over log_prob_l. Introduced a stable, scaled margin using cost_gap instead of cost_a to better capture relative example importance and to encourage separation in preference direction. The loss penalizes only cases where losing log prob surpasses winning plus margin, weighted by example weight and modulated by cost_gap normalized to avoid extreme scaling, improving gradient direction consistency and clearing co_gate failures.",
  "pseudocode": "margin_scaled = margin * (cost_gap / (mean(cost_gap) + 1e-8))\nloss = weight * relu(log_prob_l - log_prob_w + margin_scaled)\nfinal_loss = mean(loss)",
  "hyperparams": {
    "margin": 1.0
  },
  "operators_used": [
    "ops.relu",
    "ops.mean"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_gap"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    cost_gap = batch[\"cost_gap\"]\n\n    margin = 1.0\n    cost_gap_mean = ops.mean(cost_gap)\n    cost_gap_norm = cost_gap / (cost_gap_mean + 1e-8)\n\n    margin_scaled = margin * cost_gap_norm\n    diff = log_prob_l - log_prob_w + margin_scaled\n    loss = weight * ops.relu(diff)\n\n    return ops.mean(loss)"
}

