{
  "name": "pairwise_cost_gap_weighted_hinge_relaxed_maxnorm_repaired",
  "intuition": "Shift paradigm to a hinge-like max-margin loss emphasizing positive cost gaps with a relaxed margin and max-norm aggregation. A hinge loss penalizes margin less than mu plus cost gap scaling, weighted by sample weight. Aggregate by clamped max for stability, ensuring safe clamping and weighted mean return.",
  "pseudocode": "margin = log_prob_w - log_prob_l\nadjusted_margin = margin - beta * cost_gap\nhinge_loss = relu(mu - adjusted_margin)\nweighted_loss = hinge_loss * weight\nloss = weighted_loss.clamp(min=0).mean()",
  "hyperparams": {
    "paradigm_family": "pairwise_max_margin_hinge",
    "signal_family": "cost_gap",
    "link_family": "relu_hinge",
