  },
  "operators_used": ["relu", "sub", "mul", "clamp", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    cost_gap = batch['cost_gap']\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 1.0)))\n    mu = float(extra.get('mu', extra.get('hyperparams', {}).get('mu', 1.0)))\n\n    margin = ops.sub(lpw, lpl)\n    adjusted_margin = ops.sub(margin, ops.mul(beta, cost_gap))\n    hinge_loss = ops.relu(ops.sub(mu, adjusted_margin))\n    weighted_loss = ops.mul(hinge_loss, weight)\n    clamped_loss = weighted_loss.clamp(min=0)\n    return clamped_loss.mean()"
}

